fn getdomain(x: Vec<i8>) -> Vec<i8> {
    // Since the problem guarantees a non-empty input, we can safely
    // initialize min and max from the first element.
    let mut min = x[0];
    let mut max = x[0];

    // Iterate over the rest of the elements and update min and max.
    for &val in x.iter().skip(1) {
        if val < min {
            min = val;
        }
        if val > max {
            max = val;
        }
    }

    // Return a two-element Vec: [min, max]
    vec![min, max]
}

